import { useEffect, useState } from "react";
import axios from "axios";

function Schedule() {
  const [medicines, setMedicines] = useState([]);

  const days = [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
  ];

  useEffect(() => {
    axios
      .get("http://localhost:5000/medicines")
      .then((res) => setMedicines(res.data))
      .catch((err) => console.log(err));
  }, []);

  return (
    <div className="schedule-container">
      <h1>Weekly Medicine Schedule</h1>

      <table className="schedule-table">
        <thead>
          <tr>
            <th>Day</th>
            <th>Medicine</th>
            <th>Dosage</th>
            <th>Time</th>
            <th>Frequency</th>
          </tr>
        </thead>

        <tbody>
          {days.map((day) =>
            medicines.map((med) => (
              <tr key={`${day}-${med._id}`}>
                <td>{day}</td>
                <td>{med.medicineName}</td>
                <td>{med.dosage}</td>
                <td>{med.time}</td>
                <td>{med.frequency}</td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}

export default Schedule;
